/**
 * Label for one line of a bill. Fee and discount lines are generated by the
 * server in English, so they're shown by type in the reader's language;
 * adjustment lines carry the reason the operator typed and are shown as written.
 */
export function invoiceItemLabel(
  item: { type: 'fee' | 'discount' | 'adjustment'; description: string },
  t: (key: string) => string,
): string {
  return item.type === 'adjustment' ? item.description : t(`billing.item.${item.type}`)
}

/** Signed money for a bill line: "RM 150.00" or "- RM 20.00". */
export function formatSignedMoney(amount: number | string): string {
  const value = Number(amount)
  const formatted = Math.abs(value).toLocaleString('en-MY', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })
  return value < 0 ? `- RM ${formatted}` : `RM ${formatted}`
}

/**
 * A route's monthly price for a package. The base fee is the return price;
 * one-way falls back to it until the operator sets a separate one-way fee.
 */
export function routeFeeFor(
  route: { base_monthly_fee: string | null; one_way_monthly_fee: string | null } | null | undefined,
  packageType: 'one_way' | 'return',
): string | null {
  if (!route) return null
  return packageType === 'one_way'
    ? (route.one_way_monthly_fee ?? route.base_monthly_fee)
    : route.base_monthly_fee
}
